// Category A — a kitchen ticket: one order as the kitchen works it. A POS shows these on its 현황 card
// board, and an owner app and a pickup detail reuse it. The header names the order and how long it has waited, tinted once it is
// overdue; each line is pressed when it is made, and turns struck and checked; the footer calls the
// customer and completes the order. KanbanBoard's cards carry none of the line list, the per-line done
// state or the timer tint.
//
// Each line renders React Aria's ToggleButton (Category A): pressed means made. A toggle is heard as
// "pressed", which does not say "made", so every line is described by `doneHint` ("누르면 만든 메뉴로
// 표시돼요"). A checkbox would say "checked" no better and would read as a form field. Long orders show
// their first `collapsedLines` lines and an expand Button; expanding moves focus to the first revealed
// line, since the Button leaves.
//
// Overdue is never colour alone: `isOverdue` comes with `overdueLabel`, read after the elapsed time.
//
// The completing action is the footer's primary and calling the customer the outline beside it, by
// the action ladder (prop-usage-contract.md), not 호출 as the primary. Alone, the complete
// action spans the card; with 호출 both hug their labels at the end, so a label like 「6개 · 완료」
// never wraps in a narrow card (a half-width split did).
import { useId, useRef, useState } from "react";
import { Button as AriaButton, ToggleButton } from "react-aria-components";
import { Check, ChevronDown, ChevronRight } from "./icons";
import type { ReactNode, Ref } from "react";
import { Button } from "./Button";
import { ButtonGroup } from "./ButtonGroup";
import "./OrderTicket.css";

export interface OrderTicketLine {
  /** Stable key, used in `done`. */
  id: string;
  /** How many. */
  quantity: number;
  /** The item's name. */
  name: string;
  /** The chosen options, each on its own sub-line. */
  options?: string[];
}

export interface OrderTicketBaseProps {
  /**
   * Size axis: the type rung and the footer Buttons.
   *
   * @default "medium"
   */
  size?: "small" | "medium" | "large";
  /** Where the order came from, e.g. an Avatar reading "키" for the kiosk. Give it its own name. */
  source?: ReactNode;
  /** The order's name, e.g. "매장 #01". */
  title: string;
  /** A tag beside the title, e.g. a Badge "추가". */
  badge?: ReactNode;
  /** How long it has waited, e.g. "15분 전". */
  elapsed: string;
  /** The lines, in the order they print. */
  lines: OrderTicketLine[];
  /** The ids of the lines already made. */
  done: string[];
  /** Called with the ids made after a line is pressed. */
  onDoneChange: (done: string[]) => void;
  /** Describes every line's toggle, e.g. "누르면 만든 메뉴로 표시돼요". */
  doneHint: string;
  /** Label of the completing action, e.g. "3개・완료". */
  completeLabel: string;
  /** Called when the order is completed. */
  onComplete: () => void;
  /** Called when the title is pressed, to open the order. Without it the title is plain text. */
  onOpen?: () => void;
  /**
   * The title's heading level, so the ticket fits the page's outline.
   *
   * @default 3
   */
  level?: 2 | 3 | 4 | 5 | 6;
}

export type OrderTicketProps = OrderTicketBaseProps &
  (
    | {
        /** When true the order has waited too long: the header and the elapsed time take the overdue tint. */
        isOverdue: boolean;
        /** Said after the elapsed time while overdue, e.g. "지연". */
        overdueLabel: string;
      }
    | { isOverdue?: undefined; overdueLabel?: undefined }
  ) &
  (
    | {
        /** How many lines show before the expand Button. */
        collapsedLines: number;
        /** Label of the expand Button, e.g. "펼치기". */
        expandLabel: string;
      }
    | { collapsedLines?: undefined; expandLabel?: undefined }
  ) &
  (
    | {
        /** Label of the call action, e.g. "호출". */
        callLabel: string;
        /** Calls the customer. */
        onCall: () => void;
      }
    | { callLabel?: undefined; onCall?: undefined }
  ) & {
    /** Additional class (optional). sd-order-ticket is always preserved. */
    className?: string;
    /** Forwarded to the root element. */
    ref?: Ref<HTMLElement>;
  };

export function OrderTicket({
  size = "medium",
  source,
  title,
  badge,
  elapsed,
  lines,
  done,
  onDoneChange,
  doneHint,
  completeLabel,
  onComplete,
  onOpen,
  level = 3,
  isOverdue = false,
  overdueLabel,
  collapsedLines,
  expandLabel,
  callLabel,
  onCall,
  className,
  ref,
}: OrderTicketProps) {
  const titleId = useId();
  const hintId = useId();
  const listRef = useRef<HTMLUListElement>(null);
  const [expanded, setExpanded] = useState(false);
  const Heading = `h${level}` as const;
  const expand = () => {
    setExpanded(true);
    // The Button unmounts; the first revealed line takes focus once it renders.
    requestAnimationFrame(() => listRef.current?.querySelectorAll("button")[collapsedLines ?? 0]?.focus());
  };
  const limit = collapsedLines !== undefined && !expanded ? collapsedLines : lines.length;
  const shown = lines.slice(0, limit);
  const toggle = (id: string, on: boolean) => onDoneChange(on ? [...done, id] : done.filter((d) => d !== id));

  return (
    <article ref={ref} aria-labelledby={titleId} data-size={size} className={className ? `sd-order-ticket ${className}` : "sd-order-ticket"}>
      <header className="sd-order-ticket__header" data-size={size} data-overdue={isOverdue || undefined}>
        {source}
        <Heading id={titleId} className={`sd-order-ticket__title sd-type-label-${size}-emphasized`}>
          {onOpen ? (
            <AriaButton className="sd-order-ticket__open" onPress={onOpen}>
              {title}
              <ChevronRight aria-hidden size="1em" />
            </AriaButton>
          ) : (
            title
          )}
        </Heading>
        {badge}
        <span className={`sd-order-ticket__elapsed sd-type-label-${size}`} data-overdue={isOverdue || undefined}>
          {elapsed}
          {isOverdue && <span className="sd-visually-hidden">, {overdueLabel}</span>}
        </span>
      </header>
      <span id={hintId} hidden>
        {doneHint}
      </span>
      <ul ref={listRef} className="sd-order-ticket__lines">
        {shown.map((l) => {
          const isDone = done.includes(l.id);
          return (
            <li key={l.id}>
              <ToggleButton
                className="sd-order-ticket__line"
                isSelected={isDone}
                aria-describedby={hintId}
                onChange={(on) => toggle(l.id, on)}
              >
                <span className={`sd-order-ticket__quantity sd-type-body-${size}`}>{l.quantity}</span>
                <span className="sd-order-ticket__item" data-done={isDone || undefined}>
                  <span className={`sd-type-body-${size}`}>{l.name}</span>
                  {l.options?.map((o) => (
                    <span key={o} className={`sd-order-ticket__option sd-type-body-${size}`}>
                      <span aria-hidden="true">ㄴ </span>
                      {o}
                    </span>
                  ))}
                </span>
                {isDone && <Check aria-hidden size="1em" className="sd-order-ticket__check" />}
              </ToggleButton>
            </li>
          );
        })}
      </ul>
      {limit < lines.length && expandLabel && (
        <Button className="sd-order-ticket__expand" variant="secondary" size={size} onPress={expand}>
          <ChevronDown aria-hidden size="1em" />
          {expandLabel}
        </Button>
      )}
      <footer className="sd-order-ticket__footer" data-size={size}>
        <ButtonGroup layout={callLabel ? "end" : "stack"}>
          {callLabel && (
            <Button variant="secondary" size={size} onPress={onCall}>
              {callLabel}
            </Button>
          )}
          {/* usage: completing-action — completing the order is the ticket's forward action */}
          <Button variant="primary" size={size} onPress={onComplete}>
            {completeLabel}
          </Button>
        </ButtonGroup>
      </footer>
    </article>
  );
}

/* A card: the header band, the line list, an expand Button and the footer actions in a column. A made
   line is tinted, struck and checked; an overdue header takes the overdue tint. Each line pads its
   inline sides by the header's padding at the card's size, so the title and the quantities start on
   one line. */
.sd-order-ticket[data-size="small"] {
  border-radius: var(--sd-order-ticket-radius-small);
  corner-shape: superellipse(var(--sd-radius-curve));
  --sd-order-ticket-line-padding-inline-current: var(--sd-order-ticket-header-padding-small);
}
.sd-order-ticket[data-size="medium"] {
  border-radius: var(--sd-order-ticket-radius-medium);
  corner-shape: superellipse(var(--sd-radius-curve));
  --sd-order-ticket-line-padding-inline-current: var(--sd-order-ticket-header-padding-medium);
}
.sd-order-ticket[data-size="large"] {
  border-radius: var(--sd-order-ticket-radius-large);
  corner-shape: superellipse(var(--sd-radius-curve));
  --sd-order-ticket-line-padding-inline-current: var(--sd-order-ticket-header-padding-large);
}

.sd-order-ticket {
  display: flex;
  flex-direction: column;
  overflow: clip;
  border: var(--sd-order-ticket-border-width) solid var(--sd-order-ticket-border);
  background: var(--sd-order-ticket-background);
  color: var(--sd-order-ticket-foreground);
}

.sd-order-ticket__header {
  display: flex;
  align-items: center;
  gap: var(--sd-order-ticket-header-gap);
}

.sd-order-ticket__header[data-overdue] {
  background: var(--sd-order-ticket-overdue-background);
}

.sd-order-ticket__title {
  flex: 1;
  min-inline-size: 0;
  margin: 0;
}

/* The title and each quantity are text the ticket draws on its own painted surface, so they take the
   text inset (component-contract.md §6 rule 8, component-owned text). On the heading, not on the
   pressable inside it, so the pressable and its ring keep hugging the words. Inline only. */
.sd-order-ticket__title,
.sd-order-ticket__quantity {
  padding-inline: var(--sd-order-ticket-text-padding-inline);
}

.sd-order-ticket__open {
  display: inline-flex;
  align-items: center;
  gap: var(--sd-order-ticket-open-gap);
  margin: 0;
  padding: 0;
  border: none;
  border-radius: var(--sd-order-ticket-open-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
  outline: none;
}
.sd-order-ticket__open[data-hovered] {
  text-decoration: underline;
}
.sd-order-ticket__open[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-order-ticket__elapsed {
  flex: 0 0 auto;
  color: var(--sd-order-ticket-elapsed-foreground);
  font-variant-numeric: tabular-nums;
}
.sd-order-ticket__elapsed[data-overdue] {
  color: var(--sd-order-ticket-overdue-foreground);
}

.sd-order-ticket__lines {
  margin: 0;
  padding: 0;
  list-style: none;
}

.sd-order-ticket__line {
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-columns: var(--sd-order-ticket-quantity-width) minmax(0, 1fr) auto;
  align-items: start;
  gap: var(--sd-order-ticket-line-gap);
  inline-size: 100%;
  margin: 0;
  padding: var(--sd-order-ticket-line-padding) var(--sd-order-ticket-line-padding-inline-current);
  border: none;
  background: transparent;
  color: inherit;
  text-align: start;
  cursor: pointer;
  outline: none;
  /* The wash each state lays over this part: the surface wash, or over a fill the one named for that
     fill, which goes away from its inks (contrast-contract.mjs § the state layer over a fill). */
  --sd-order-ticket-line-state-hover-current: var(--sd-state-hover);
  --sd-order-ticket-line-state-pressed-current: var(--sd-state-pressed);
  /* The muted inks inside the line, raised to the ticket's own while it is hovered or pressed. */
  --sd-order-ticket-done-current: var(--sd-order-ticket-done-foreground);
  --sd-order-ticket-option-current: var(--sd-order-ticket-option-foreground);
}
/* Raised to the row's own ink while it is hovered or pressed: this ink is derived at its floor and
   falls under 4.5:1 over the surface wash (contrast-contract.mjs § SURFACE_WASH_INKS). */
.sd-order-ticket__line[data-hovered],
.sd-order-ticket__line[data-pressed] {
  --sd-order-ticket-done-current: var(--sd-order-ticket-foreground);
  --sd-order-ticket-option-current: var(--sd-order-ticket-foreground);
}
.sd-order-ticket__line[data-selected] {
  background: var(--sd-order-ticket-done-background);
  --sd-order-ticket-line-state-hover-current: var(--sd-state-hover-selected);
  --sd-order-ticket-line-state-pressed-current: var(--sd-state-pressed-selected);
}
.sd-order-ticket__line::after {
  content: "";
  position: absolute;
  inset: 0;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
}
.sd-order-ticket__line[data-hovered]::after {
  background: var(--sd-order-ticket-line-state-hover-current);
}
.sd-order-ticket__line[data-pressed]::after {
  background: var(--sd-order-ticket-line-state-pressed-current);
}
.sd-order-ticket__line[data-focus-visible] {
  box-shadow: inset 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-order-ticket__quantity {
  font-variant-numeric: tabular-nums;
}

.sd-order-ticket__item {
  display: flex;
  flex-direction: column;
  gap: var(--sd-order-ticket-option-gap);
  overflow-wrap: anywhere;
}
.sd-order-ticket__item[data-done] {
  color: var(--sd-order-ticket-done-current);
  text-decoration: line-through;
}

.sd-order-ticket__option {
  color: var(--sd-order-ticket-option-current);
}

.sd-order-ticket__check {
  color: var(--sd-order-ticket-check-foreground);
}

.sd-order-ticket__expand {
  align-self: center;
  margin-block: var(--sd-order-ticket-line-gap);
}

.sd-order-ticket__footer {
  margin-block-start: auto;
}

/* Header and footer take the surface padding at the card's tier, the pair of its corner. */
.sd-order-ticket__header[data-size="small"] {
  padding: var(--sd-order-ticket-header-padding-small);
}
.sd-order-ticket__footer[data-size="small"] {
  padding: var(--sd-order-ticket-footer-padding-small);
}
.sd-order-ticket__header[data-size="medium"] {
  padding: var(--sd-order-ticket-header-padding-medium);
}
.sd-order-ticket__footer[data-size="medium"] {
  padding: var(--sd-order-ticket-footer-padding-medium);
}
.sd-order-ticket__header[data-size="large"] {
  padding: var(--sd-order-ticket-header-padding-large);
}
.sd-order-ticket__footer[data-size="large"] {
  padding: var(--sd-order-ticket-footer-padding-large);
}
